const $=s=>document.querySelector(s);let records=[],saved=[],onlySaved=false,timer;try{saved=JSON.parse(localStorage.getItem('bonchorok-bookmarks')||'[]');if(!Array.isArray(saved))saved=[]}catch{}function notify(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2300)}function render(){const q=$('#search').value.trim().toLowerCase();const filtered=records.filter(r=>(!onlySaved||saved.includes(r.id))&&[r.name,r.hanja,r.english,r.latin,r.plant].join(' ').toLowerCase().includes(q));$('#results').replaceChildren();filtered.forEach(r=>{const b=document.createElement('button');b.className='herb-row';b.innerHTML='<img src="sophora.jpg" alt=""><span><strong></strong><small></small></span><span class="row-star"></span>';b.querySelector('strong').textContent=r.name+' '+r.hanja;b.querySelector('small').textContent=r.latin;b.querySelector('.row-star').textContent=saved.includes(r.id)?'★':'›';b.onclick=()=>{$('.workspace').classList.remove('show-library');window.scrollTo({top:0,behavior:'smooth'})};$('#results').append(b)});if(!filtered.length){const p=document.createElement('p');p.className='list-empty';p.textContent=onlySaved?'저장한 약재가 없습니다.':'검색 결과가 없습니다.';$('#results').append(p)}$('#result-count').textContent=filtered.length+'종';const yes=saved.includes('sophorae-flos');$('#bookmark').textContent=yes?'★':'☆';$('#bookmark').setAttribute('aria-pressed',String(yes));$('#bookmark').setAttribute('aria-label',yes?'괴화 북마크 해제':'괴화 북마크 추가');$('#saved-count').textContent=saved.length;$('#all-filter').classList.toggle('active',!onlySaved);$('#bookmark-filter').classList.toggle('active',onlySaved)}function setBookmark(value){saved=value?[...new Set([...saved,'sophorae-flos'])]:saved.filter(x=>x!=='sophorae-flos');try{localStorage.setItem('bonchorok-bookmarks',JSON.stringify(saved));notify(value?'이 기기에 괴화를 저장했습니다.':'북마크를 해제했습니다.')}catch{notify('현재 화면에 저장했습니다. 브라우저 저장소를 사용할 수 없습니다.')}render();return{saved:value}}$('#bookmark').onclick=()=>setBookmark(!saved.includes('sophorae-flos'));$('#search').oninput=render;$('#all-filter').onclick=()=>{onlySaved=false;render()};$('#bookmark-filter').onclick=()=>{onlySaved=true;render()};$('#saved-nav').onclick=()=>{onlySaved=true;render();$('.workspace').classList.add('show-library');$('#search').focus()};$('#back-list').onclick=()=>{onlySaved=false;render();$('.workspace').classList.add('show-library');$('#search').focus()};$('.brand').onclick=()=>{$('.workspace').classList.remove('show-library')};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('.workspace').classList.add('show-library');$('#search').focus()}});function gallery(type){document.querySelectorAll('[data-gallery]').forEach(b=>b.classList.toggle('active',b.dataset.gallery===type));$('#gallery-content').innerHTML=type==='plant'?'<img class="gallery-photo" src="sophora.jpg" alt="회화나무의 크림색 꽃과 초록 잎" loading="lazy"><p class="photo-credit"><a href="https://commons.wikimedia.org/wiki/File:Sophora_japonica_JPG2Fl.jpg" target="_blank" rel="noopener">Jean-Pol GRANDMONT / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a> · 일부 크롭</p>':'<div class="empty-block"><h3>확인된 이미지가 아직 없습니다</h3><p>출처와 품종이 확인된 자료를 등록한 뒤 제공됩니다.</p></div>'}document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>gallery(b.dataset.gallery));gallery('plant');new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.toc>a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}})},{rootMargin:'-15% 0px -65% 0px'}).observe($('#basic'));document.querySelectorAll('.content-section').forEach(s=>new IntersectionObserver(es=>{if(es[0].isIntersecting)document.querySelectorAll('.toc>a').forEach(a=>a.classList.toggle('active',a.hash==='#'+s.id))},{rootMargin:'-15% 0px -65% 0px'}).observe(s));fetch('herbs.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{records=data;render()}).catch(()=>{$('#results').textContent='자료를 불러오지 못했습니다. 새로고침해 주세요.'});if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'set_herb_bookmark',description:'현재 괴화 자료의 기기 내 북마크를 추가하거나 해제합니다.',inputSchema:{type:'object',properties:{saved:{type:'boolean'}},required:['saved'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.saved!=='boolean')throw Error('saved must be boolean');return setBookmark(input.saved)}})).catch(()=>{})}catch{}
